namespace {

/**
 * @brief Target position spin boxes in joint-space (`Joint::Name`) order,
 *        independent of UI layout, for input parsers.
 *
 * @param ui Pointer to main UI object
 *
 * @see Joint::Name
 */
std::vector<QDoubleSpinBox*> GetOrderedSpinBoxes(const Ui::MainWindow* ui) {
#if LIBRA_VERSION == 1
    return {ui->sb_arm_roll, ui->sb_arm_pitch, ui->sb_arm_j1, ui->sb_arm_j2,
            ui->sb_arm_j3};
#elif LIBRA_VERSION == 2
    return {ui->sb_arm_yaw, ui->sb_arm_pitch};
#else
    return {};
#endif
}

}  // namespace

//------------------------------------------------------------------------------
// !Class Helpers
//------------------------------------------------------------------------------

/**
 * @brief Moves the arm to the given joint angles.
 *
 * @param targets Joint angles, indexed by `Joint::Name` (deg)
 */
void MainWindow::SendJointTargets(const std::vector<double>& targets) {
    std::vector<double> actuator_targets(Actuator::kUndefined, 0.0);

    // Lambdas to improve readability of conversions (joint -> actuator)
    auto convert_and_set_simple = [&](Actuator::Name name, double val) {
        actuator_targets[name] = Actuator::JointToActuatorSimple(name, val);
    };
#if LIBRA_VERSION == 1
    auto convert_and_set_diff = [&](Actuator::Name name, double roll,
                                    double pitch) {
        actuator_targets[name] = Actuator::JointToActuatorDifferential(name,
                                                                       roll,
                                                                       pitch);
    };
#endif

    // Convert joint angles to actuator command angles
#if LIBRA_VERSION == 1
    const double roll = targets[Joint::Name::kRoll];
    const double pitch = targets[Joint::Name::kPitch];

    convert_and_set_diff(Actuator::kMA, roll, pitch);
    convert_and_set_diff(Actuator::kMB, roll, pitch);
    convert_and_set_simple(Actuator::kJ1, targets[Joint::Name::kJ1]);
    convert_and_set_simple(Actuator::kJ2, targets[Joint::Name::kJ2]);
    convert_and_set_simple(Actuator::kJ3, targets[Joint::Name::kJ3]);
#elif LIBRA_VERSION == 2
    convert_and_set_simple(Actuator::kYaw, targets[Joint::Name::kYaw]);
    convert_and_set_simple(Actuator::kPitch, targets[Joint::Name::kPitch]);
#endif

    if (debug_mode_) {
        std::stringstream command_ss;
        command_ss << std::fixed << std::setprecision(2)
                   << "Sending movement command (deg): ";

        for (int i = 0; i < Actuator::kUndefined; ++i) {
            const auto actuator = static_cast<Actuator::Name>(i);
            command_ss << Actuator::NameEnumToString(actuator) << "="
                       << actuator_targets[actuator];

            if (i < Actuator::kUndefined - 1) {
                command_ss << ", ";
            }
        }

        logger_->Debug(command_ss.str());
    }

    // Send command(s)
#if LIBRA_VERSION == 1
    emit CommandHebi(actuator_targets);
#elif LIBRA_VERSION == 2
    emit CommandEpos({actuator_targets[Actuator::kYaw]});
    emit CommandHebi({actuator_targets[Actuator::kPitch]});
#endif

    previous_target_ = std::exchange(current_target_, targets);

    // UI widgets
    UpdateActuatorControls();
}

//------------------------------------------------------------------------------
// !Buttons
//------------------------------------------------------------------------------

/**
 * @brief Sets all actuator target values in the UI using a comma-delimited
 *        string of values.
 *
 * @note This is a stop-gap approach, since end-effector tracking (i.e., inverse
 *       kinematics) is not yet implemented.
 */
void MainWindow::on_pb_quick_input_clicked() {
    const auto input = ui_->le_quick_input->text();

    if (input.isEmpty()) {
        logger_->Warn("No values entered");
        return;
    }

    // Parse input (format and delimiter are automatically validated)
    const auto values = input.split(',', Qt::SkipEmptyParts);
    const auto target_boxes = GetOrderedSpinBoxes(ui_);

    if (static_cast<size_t>(values.size()) != target_boxes.size()) {
        logger_->Warn("Provided values (" + std::to_string(values.size())
                      + ") != No. of actuators ("
                      + std::to_string(target_boxes.size()) + "); ignoring");
        return;
    }

    // Set UI values (each Spin Box's min/max is automatically respected)
    for (size_t i = 0; i < target_boxes.size(); ++i) {
        target_boxes[i]->setValue(values[i].toDouble());
    }

    // Clear the input box
    ui_->le_quick_input->clear();
}

/**
 * @brief Sends the target spin boxes' values to all actuators.
 */
void MainWindow::on_pb_arm_start_clicked() {
    std::vector<double> targets(Motion::kNumJoints, 0.0);
    for (const auto& [joint, spin_box] : target_spin_box_map_) {
        targets[joint] = spin_box->value();
    }

    SendJointTargets(targets);
}

/**
 * @brief Pauses trajectory playback, if active.
 *
 * @note The actuators themselves are stopped via signals (see
 *       `InitializeThreads()`).
 */
void MainWindow::on_pb_arm_stop_clicked() {
    if (!trajectory_playing_) {
        return;
    }

    logger_->Info("Trajectory paused at step "
                  + GetTrajectoryStepText().toStdString());
    SetTrajectoryPlaying(false);
}

/**
 * @brief Moves all actuators back to the previous target.
 *
 * @note Only goes back one target; button stays disabled until a new target is
 *       sent (so an accidental multi-click can't move the arm further).
 */
void MainWindow::on_pb_arm_return_clicked() {
    logger_->Info("Returning to the previous target");

    SendJointTargets(previous_target_);
    previous_target_ = current_target_;

    UpdateActuatorControls();
}

/**
 * @brief Requests the motion mode picked by the user, if its requirements are
 *        met; otherwise explains what's missing and resets to the current mode.
 *
 * @param index Picked list item
 *
 * @see SetMotionMode
 */
void MainWindow::on_cb_motion_mode_activated(int index) {
    const auto mode = static_cast<Motion::MotionMode>(
        ui_->cb_motion_mode->itemData(index).toInt());
    if (mode == motion_mode_) {
        return;
    }

    // Check the mode's requirements
    QString missing;
    if (mode != Motion::MotionMode::kManual
        && !ui_->a_water_cw_disconnect->isEnabled()) {
        missing = "a connected CW (see \"Water\" menu)";
    }
#if LIBRA_VERSION == 2
    if (missing.isEmpty() && Motion::UsesMotionController(mode)
        && motion_controller_->GetCalibration() != Motion::Calibration::kFull) {
        missing = "arm and friction calibrations (see \"Motion Control\" menu)";
    }
#endif

    if (!missing.isEmpty()) {
        const auto name = QString::fromStdString(
            Motion::MotionModeEnumToString(mode));
        logger_->Warn(name.toStdString() + " mode needs "
                      + missing.toStdString() + "; staying in the current mode");
        QMessageBox::warning(this, "Motion Mode",
                             name + " mode needs " + missing + ".");

        ui_->cb_motion_mode->setCurrentIndex(
            ui_->cb_motion_mode->findData(static_cast<int>(motion_mode_)));
        return;
    }

    SetMotionMode(mode);
}
